package com.peiwan.platform.payment;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper;import com.peiwan.platform.persistence.entity.*;import com.peiwan.platform.persistence.mapper.*;import com.peiwan.platform.wallet.WalletService;import org.springframework.context.ApplicationEventPublisher;import org.springframework.dao.DuplicateKeyException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.LocalDateTime;import java.time.format.DateTimeFormatter;import java.util.*;
@Service public class OrderPaymentService{
 private final OrderPaymentMapper payments;private final OrderPaymentDataMapper data;private final WalletAccountMapper wallets;private final WalletDataMapper walletData;private final WalletTransactionMapper transactions;private final OrderStatusLogMapper orderLogs;private final ApplicationEventPublisher events;private final WalletService walletService;
 public OrderPaymentService(OrderPaymentMapper payments,OrderPaymentDataMapper data,WalletAccountMapper wallets,WalletDataMapper walletData,WalletTransactionMapper transactions,OrderStatusLogMapper orderLogs,ApplicationEventPublisher events,WalletService walletService){this.payments=payments;this.data=data;this.wallets=wallets;this.walletData=walletData;this.transactions=transactions;this.orderLogs=orderLogs;this.events=events;this.walletService=walletService;}
 @Transactional public Map<String,Object> pay(long uid,long orderId,String requestNo){requestNo=validRequestNo(requestNo);var byRequest=findRequest(uid,requestNo);if(byRequest!=null){if(!Objects.equals(byRequest.orderId,orderId))throw new IllegalArgumentException("请求流水号已用于其他订单");return view(byRequest,true);}var order=data.lockOrder(orderId);if(order==null||!Objects.equals(order.customerId,uid))throw new IllegalArgumentException("订单不存在或不属于当前用户");var existing=findOrder(orderId);if(existing!=null)return view(existing,true);if(!"PENDING_PAYMENT".equals(order.orderStatus))throw new IllegalArgumentException("当前订单不能支付");var wallet=lockWallet(uid);BigDecimal payable=order.payableAmount;BigDecimal cash=wallet.cashBalance.min(payable);BigDecimal bonus=payable.subtract(cash);if(wallet.bonusBalance.compareTo(bonus)<0)throw new IllegalArgumentException("钱包余额不足");String no=paymentNo("PAY");var p=payment(uid,orderId,requestNo,no,"BALANCE",payable,cash,bonus);try{payments.insert(p);}catch(DuplicateKeyException e){var duplicate=findOrder(orderId);if(duplicate!=null)return view(duplicate,true);throw new IllegalArgumentException("请求流水号已存在");}if(data.debit(wallet.id,cash,bonus)!=1)throw new IllegalArgumentException("钱包余额不足");if(cash.signum()>0)addTx(wallet,uid,"CASH","OUT","ORDER_PAYMENT",no,cash,wallet.cashBalance,wallet.cashBalance.subtract(cash),"订单余额支付");if(bonus.signum()>0)addTx(wallet,uid,"BONUS","OUT","ORDER_PAYMENT",no,bonus,wallet.bonusBalance,wallet.bonusBalance.subtract(bonus),"订单赠送余额支付");walletService.refreshMembership(uid);markPaid(orderId,payable,uid,"余额支付完成");return view(p,false);}
 @Transactional public Map<String,Object> mockWechatPay(long uid,long orderId,String requestNo){requestNo=validRequestNo(requestNo);var byRequest=findRequest(uid,requestNo);if(byRequest!=null){if(!Objects.equals(byRequest.orderId,orderId))throw new IllegalArgumentException("请求流水号已用于其他订单");return view(byRequest,true);}var order=data.lockOrder(orderId);if(order==null||!Objects.equals(order.customerId,uid))throw new IllegalArgumentException("订单不存在或不属于当前用户");var existing=findOrder(orderId);if(existing!=null)return view(existing,true);if(!"PENDING_PAYMENT".equals(order.orderStatus))throw new IllegalArgumentException("当前订单不能支付");var p=payment(uid,orderId,requestNo,paymentNo("WXP"),"MOCK_WECHAT",order.payableAmount,BigDecimal.ZERO,BigDecimal.ZERO);try{payments.insert(p);}catch(DuplicateKeyException e){var duplicate=findOrder(orderId);if(duplicate!=null)return view(duplicate,true);throw new IllegalArgumentException("请求流水号已存在");}markPaid(orderId,order.payableAmount,uid,"模拟微信支付完成");return view(p,false);}
 @Transactional public Map<String,Object> manualPay(long uid,long orderId,String requestNo,long operator,String channel){requestNo=validRequestNo(requestNo);if(!Set.of("MANUAL_CASH","MANUAL_WECHAT","MANUAL_ALIPAY","MANUAL_OTHER").contains(channel))throw new IllegalArgumentException("后台收款方式无效");var order=data.lockOrder(orderId);if(order==null||!Objects.equals(order.customerId,uid))throw new IllegalArgumentException("订单不存在或下单用户不匹配");var existing=findOrder(orderId);if(existing!=null)return view(existing,true);if(!"PENDING_PAYMENT".equals(order.orderStatus))throw new IllegalArgumentException("当前订单不能确认收款");var p=payment(uid,orderId,requestNo,paymentNo("MPAY"),channel,order.payableAmount,BigDecimal.ZERO,BigDecimal.ZERO);payments.insert(p);markPaid(orderId,order.payableAmount,operator,"后台确认收款");return view(p,false);}
 @Transactional public void refundOrder(long orderId,Long operator,String reason){var order=data.lockOrder(orderId);if(order==null)throw new IllegalArgumentException("订单不存在");var p=findOrder(orderId);if(p==null)return;if("REFUNDED".equals(p.paymentStatus))return;if(!"PAID".equals(p.paymentStatus))throw new IllegalArgumentException("订单支付状态不能退款");if("BALANCE".equals(p.paymentChannel)){var wallet=lockWallet(p.userId);BigDecimal beforeCash=wallet.cashBalance,beforeBonus=wallet.bonusBalance;data.refund(wallet.id,p.cashAmount,p.bonusAmount);String businessNo=p.paymentNo;if(p.cashAmount.signum()>0)addTx(wallet,p.userId,"CASH","IN","ORDER_REFUND",businessNo,p.cashAmount,beforeCash,beforeCash.add(p.cashAmount),"订单取消退款");if(p.bonusAmount.signum()>0)addTx(wallet,p.userId,"BONUS","IN","ORDER_REFUND",businessNo,p.bonusAmount,beforeBonus,beforeBonus.add(p.bonusAmount),"订单取消退回赠送余额");walletService.refreshMembership(p.userId);}p.paymentStatus="REFUNDED";p.refundedCashAmount=p.cashAmount;p.refundedBonusAmount=p.bonusAmount;p.refundedAt=LocalDateTime.now();p.updatedAt=LocalDateTime.now();payments.updateById(p);data.markTradeRefunded(orderId,p.payableAmount);}
 public Map<String,Object> detail(long uid,long orderId){var p=payments.selectOne(new QueryWrapper<OrderPaymentEntity>().eq("order_id",orderId).eq("user_id",uid));return p==null?Map.of():view(p,false);}
 private WalletAccountEntity lockWallet(long uid){var row=walletData.lockUserWallet(uid);if(row==null){try{var w=new WalletAccountEntity();w.ownerType="USER";w.ownerId=uid;w.cashBalance=BigDecimal.ZERO;w.bonusBalance=BigDecimal.ZERO;w.frozenBalance=BigDecimal.ZERO;w.version=0L;wallets.insert(w);}catch(DuplicateKeyException ignored){}row=walletData.lockUserWallet(uid);}if(row==null)throw new IllegalArgumentException("钱包创建失败");var w=new WalletAccountEntity();w.id=((Number)row.get("id")).longValue();w.cashBalance=(BigDecimal)row.get("cash_balance");w.bonusBalance=(BigDecimal)row.get("bonus_balance");w.frozenBalance=(BigDecimal)row.get("frozen_balance");return w;}
 private void addTx(WalletAccountEntity w,long uid,String balance,String direction,String type,String businessNo,BigDecimal amount,BigDecimal before,BigDecimal after,String remark){var t=new WalletTransactionEntity();t.transactionNo="WT"+UUID.randomUUID().toString().replace("-","").toUpperCase();t.accountId=w.id;t.ownerType="USER";t.ownerId=uid;t.balanceType=balance;t.direction=direction;t.businessType=type;t.businessNo=businessNo;t.amount=amount;t.balanceBefore=before;t.balanceAfter=after;t.remark=remark;transactions.insert(t);}
 private OrderPaymentEntity payment(long uid,long orderId,String requestNo,String paymentNo,String channel,BigDecimal payable,BigDecimal cash,BigDecimal bonus){var p=new OrderPaymentEntity();p.paymentNo=paymentNo;p.requestNo=requestNo;p.orderId=orderId;p.userId=uid;p.paymentChannel=channel;p.paymentStatus="PAID";p.payableAmount=payable;p.cashAmount=cash;p.bonusAmount=bonus;p.refundedCashAmount=BigDecimal.ZERO;p.refundedBonusAmount=BigDecimal.ZERO;p.paidAt=LocalDateTime.now();return p;}private String paymentNo(String prefix){return prefix+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMddHHmmss"))+UUID.randomUUID().toString().replace("-","").substring(0,6).toUpperCase();}private void markPaid(long orderId,BigDecimal payable,long uid,String reason){if(data.markPaid(orderId,payable)!=1)throw new IllegalArgumentException("订单状态已变化，请勿重复支付");log(orderId,"PENDING_PAYMENT","WAIT_ASSIGN",uid,reason);events.publishEvent(new OrderPaidEvent(orderId,uid));}private OrderPaymentEntity findOrder(long id){return payments.selectOne(new QueryWrapper<OrderPaymentEntity>().eq("order_id",id));}private OrderPaymentEntity findRequest(long uid,String no){return payments.selectOne(new QueryWrapper<OrderPaymentEntity>().eq("user_id",uid).eq("request_no",no));}private String validRequestNo(String no){if(no==null||no.isBlank()||no.trim().length()>64)throw new IllegalArgumentException("请求流水号不能为空且不能超过64位");return no.trim();}private void log(long id,String from,String to,Long op,String reason){var l=new OrderStatusLogEntity();l.orderId=id;l.fromStatus=from;l.toStatus=to;l.operatorId=op;l.reason=reason;orderLogs.insert(l);}private Map<String,Object> view(OrderPaymentEntity p,boolean duplicate){return Map.ofEntries(Map.entry("paymentNo",p.paymentNo),Map.entry("requestNo",p.requestNo),Map.entry("orderId",p.orderId),Map.entry("paymentChannel",p.paymentChannel),Map.entry("status",p.paymentStatus),Map.entry("payableAmount",p.payableAmount),Map.entry("cashAmount",p.cashAmount),Map.entry("bonusAmount",p.bonusAmount),Map.entry("refundedCashAmount",p.refundedCashAmount),Map.entry("refundedBonusAmount",p.refundedBonusAmount),Map.entry("duplicated",duplicate));}
}
